const P=window.portfolio;
const slug=t=>t.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const esc=t=>String(t??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=u=>{try{const v=new URL(u,location.href);return ['http:','https:'].includes(v.protocol)?v.href:''}catch{return ''}};
const pages=new Map();
const main=document.querySelector('main');
const add=(id,title,kind,sem)=>pages.set(id,{id,title,kind,sem});
const finals=['Model Guru','Refleksi Akhir Praktik','Filosofi Mengajar','Rencana Tindak Lanjut','Harapan Pendidikan Indonesia','Upaya Menjadi Guru yang Profesional'];
function navLink(id,label){return `<a href="#${id}" data-page="${id}">${esc(label)}</a>`}
let nav=navLink('beranda','⌂  Beranda');
for(const s of P.semester){
 add(`artefak-s${s.nomor}`,`Artefak Semester ${s.nomor}`,'index',s);
 add(`refleksi-s${s.nomor}`,`Refleksi Mata Kuliah S${s.nomor}`,'reflection-index',s);
 nav+=`<div class="nav-label">SEMESTER ${s.nomor}</div><details><summary>Artefak Semester ${s.nomor}</summary>${navLink(`artefak-s${s.nomor}`,'Semua artefak')}`;
 for(const t of s.artefak){const id=`s${s.nomor}-${slug(t)}`;add(id,t,'artifact',s);nav+=navLink(id,t)}
 nav+=`</details><details><summary>Refleksi Mata Kuliah S${s.nomor}</summary>${navLink(`refleksi-s${s.nomor}`,'Semua refleksi')}`;
 for(const t of s.mataKuliah){const id=`refleksi-s${s.nomor}-${slug(t)}`;add(id,t,'reflection',s);nav+=navLink(id,t)}nav+='</details>';
}
nav+='<div class="nav-label">REFLEKSI & ARAH DIRI</div>';
for(const t of finals){add(slug(t),t,'reflection');nav+=navLink(slug(t),t)}
document.querySelector('#navigation').innerHTML=nav;
const tile=(id,title,sub,tag='↗')=>`<a class="tile" href="#${id}"><span class="tile-icon">${tag}</span><h3>${esc(title)}</h3><p>${esc(sub)}</p><span class="tile-bottom">JELAJAHI <span>↗</span></span></a>`;
function home(){const p=P.profil;return `<section class="intro-cover" aria-labelledby="intro-title"><div class="intro-copy"><p class="intro-eyebrow">PORTOFOLIO PPG <span>·</span> 2026</p><p class="intro-overline">PENDIDIKAN PROFESI GURU / INFORMATIKA</p><h1 id="intro-title">Muhammad<br><span>Abduramadani.</span></h1><p class="intro-role">Calon Guru Informatika<br><span>Universitas Negeri Surabaya</span></p><p class="intro-summary">Dokumentasi praktik, karya, dan refleksi dari dua semester perjalanan PPL.</p><div class="intro-actions"><button id="enterPortfolio" type="button">JELAJAHI PORTOFOLIO <span aria-hidden="true">↘</span></button><a href="#artefak-s2">LIHAT ARTEFAK <span aria-hidden="true">↗</span></a></div><div class="intro-meta"><div><span>SEMESTER 01</span><b>SMA Negeri 15 Surabaya</b></div><div><span>SEMESTER 02</span><b>SMP Negeri 60 Surabaya</b></div></div></div><div class="intro-visual" aria-label="Potret Muhammad Abduramadani"><span class="intro-year" aria-hidden="true">26</span><span class="intro-vertical">UNIVERSITAS NEGERI SURABAYA</span><div class="intro-seal"><span>PPG</span><small>INFORMATIKA</small></div><img class="intro-portrait" src="${esc(safe(p.foto))}" alt="${esc(p.nama)}" fetchpriority="high"><span class="intro-count">01 <i>—</i> 02</span></div><span class="intro-footnote">BELAJAR · MENGAJAR · BERTUMBUH</span></section><section class="editorial-hero" id="portfolio-hero"><div class="orange-field"><span class="hero-kicker">DANI / CALON GURU INFORMATIKA</span><span class="orb orb-one"></span><span class="orb orb-two"></span></div><div class="white-field"><nav class="hero-nav" aria-label="Navigasi utama"><a href="#artefak-s2">ARTEFAK</a><a href="#refleksi-s2">REFLEKSI</a><button class="hero-menu" aria-label="Buka semua menu">☰</button></nav></div><div class="editorial-copy"><p class="eyebrow">BELAJAR UNTUK MEMBERI MAKNA.</p><h1>BELAJAR.<br>MENGAJAR.</h1><p>Merancang pembelajaran.<br>Menumbuhkan potensi.</p><a class="hero-button" href="#artefak-s2">LIHAT ARTEFAK <span>↗</span></a></div><img class="hero-portrait" src="${esc(safe(p.foto))}" alt="${esc(p.nama)}" fetchpriority="high"><div class="hero-identity"><span class="status-label">PORTOFOLIO PPG <i></i></span><h2>${esc(p.nama)}</h2><p>Informatika<br>${esc(p.kampus)}</p></div><div class="hero-bottom-left"><span class="mini-index">01 — 02</span><p>Dua semester.<br>Satu perjalanan menjadi pendidik.</p></div><div class="hero-note"><span class="quote-mark">“</span><p>Belajar, mengajar,<br>dan terus bertumbuh.</p><span>${esc(p.program)}</span><a href="#artefak-s1" aria-label="Jelajahi Semester 1">↗</a></div><span class="hero-caption">E-PORTOFOLIO / 2026</span></section><div class="hero-strip"><span>PENDIDIKAN PROFESI GURU</span><span>INFORMATIKA</span><span>UNIVERSITAS NEGERI SURABAYA</span><a href="#artefak-s2">JELAJAHI PERJALANAN ↓</a></div><section class="section"><div class="section-head"><div><p class="eyebrow">01 / PROFIL MAHASISWA</p><h2>Kenali perjalanan saya.</h2></div></div><div class="profile"><div><p>${esc(p.bio)}</p>${p.email&&safe('mailto:'+p.email)?'':''}${p.email?`<p>Kontak: ${esc(p.email)}</p>`:'<p class="muted">Kontak belum ditambahkan.</p>'}</div><dl><div><dt>NAMA</dt><dd>${esc(p.nama)}</dd></div><div><dt>NIM</dt><dd>${esc(p.nim)}</dd></div><div><dt>BIDANG STUDI</dt><dd>Informatika</dd></div></dl>${p.foto&&safe(p.foto)?`<img class="profile-photo" src="${esc(safe(p.foto))}" alt="${esc(p.nama)}">`:''}</div></section><section class="section"><div class="section-head"><div><p class="eyebrow">02 / PRAKTIK & PEMBELAJARAN</p><h2>Dua semester, satu perjalanan.</h2></div><span class="pill">PORTOFOLIO 1 & 2</span></div><div class="semester-grid">${P.semester.map(s=>`<article class="semester-card"><span class="semester-number">0${s.nomor}</span><p class="eyebrow">PRAKTIK PENGALAMAN LAPANGAN</p><h3>Semester ${s.nomor}</h3><p>${esc(s.sekolah)}</p><div class="semester-links"><a href="#artefak-s${s.nomor}">Artefak pembelajaran ↗</a><a href="#refleksi-s${s.nomor}">Refleksi mata kuliah ↗</a></div></article>`).join('')}</div></section><section class="section"><div class="section-head"><div><p class="eyebrow">03 / PANDUAN PENELUSURAN</p><h2>Ikuti proses di balik pembelajaran.</h2></div></div><div class="learning-path"><div class="path-step"><span class="step-number">01</span><h3>Kenali konteks</h3><p>Mulai dari profil dan sekolah tempat pelaksanaan PPL.</p></div><div class="path-step"><span class="step-number">02</span><h3>Telusuri artefak</h3><p>Buka perangkat, media, dan dokumentasi tiap semester.</p></div><div class="path-step"><span class="step-number">03</span><h3>Baca analisis</h3><p>Pelajari tujuan, kelebihan, tantangan, dan kaitan dengan teori.</p></div><div class="path-step"><span class="step-number">04</span><h3>Temukan refleksi</h3><p>Ikuti catatan pengalaman dan rencana pengembangan diri.</p></div></div><p class="path-note">Dokumen dan catatan ditampilkan pada kategori masing-masing setelah ditambahkan.</p></section><section class="section"><div class="section-head"><div><p class="eyebrow">04 / PENGEMBANGAN DIRI</p><h2>Refleksi yang memberi arah.</h2></div></div><div class="tiles">${finals.map(t=>tile(slug(t),t,'Catatan dan arah pengembangan sebagai calon guru.','↗')).join('')}</div></section>`}
function render(){const id=decodeURIComponent(location.hash.slice(1))||'beranda';const page=pages.get(id);document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===id);a.removeAttribute('aria-current');if(a.dataset.page===id){a.setAttribute('aria-current','page');if(a.closest('details'))a.closest('details').open=true}});
if(id==='beranda'){main.innerHTML=home();document.querySelector('#enterPortfolio')?.addEventListener('click',()=>document.querySelector('#portfolio-hero')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}))}else if(!page)main.innerHTML='<section class="section"><h1>Halaman tidak ditemukan</h1><a class="button" href="#beranda">Kembali ke beranda</a></section>';else{const c=P.isi[id]||{};let body='';if(page.kind.includes('index')){const items=page.kind==='index'?page.sem.artefak:page.sem.mataKuliah;body=`<div class="tiles">${items.map(t=>{const key=page.kind==='index'?`s${page.sem.nomor}-${slug(t)}`:`refleksi-s${page.sem.nomor}-${slug(t)}`;const n=(P.isi[key]?.artefak||[]).length;return tile(key,t,page.kind==='index'?`${n} artefak ditambahkan`:'Refleksi pengalaman belajar')}).join('')}</div>`}else if(page.kind==='artifact'){body=`<div class="artifact-list">${(c.artefak||[]).map(a=>`<article class="artifact"><p class="eyebrow">${esc(a.jenis||'DOKUMEN')}${a.siklus?' / SIKLUS '+esc(a.siklus):''}</p><h2>${esc(a.judul)}</h2><p>${esc(a.deskripsi||'')}</p>${a.url&&safe(a.url)?`<a class="button" target="_blank" rel="noopener noreferrer" href="${esc(safe(a.url))}">Lihat artefak ↗</a>`:'<span class="pill">Berkas belum ditambahkan</span>'}<div class="analysis">${[['konteks','Konteks pembelajaran'],['tujuan','Tujuan'],['kelebihan','Kelebihan'],['kekurangan','Kekurangan & perbaikan'],['teori','Keterkaitan teori mata kuliah']].map(([k,l])=>`<div><h3>${l}</h3><p>${esc(a[k]||'Analisis belum ditambahkan.')}</p></div>`).join('')}</div></article>`).join('')||empty('Artefak belum ditambahkan.','Dokumen, foto, dan tautan video akan ditampilkan di sini beserta analisisnya.')}</div>`}else{body=`<article class="reading">${(c.paragraf||[]).map(t=>`<p>${esc(t)}</p>`).join('')||empty('Refleksi belum ditambahkan.','Catatan pengalaman, kekuatan, tantangan, dan rencana perbaikan akan ditampilkan di sini.')}${(c.bagian||[]).map(b=>`<h2>${esc(b.judul)}</h2><p>${esc(b.teks)}</p>`).join('')}</article>`}const backId=page.sem?(page.kind==='artifact'?`artefak-s${page.sem.nomor}`:page.kind==='reflection'?`refleksi-s${page.sem.nomor}`:'beranda'):'beranda';main.innerHTML=`<a class="back-button" href="#${backId}"><span aria-hidden="true">←</span> Kembali<span class="back-context"> ke ${esc(pages.get(backId)?.title||'Beranda')}</span></a><section class="page-head"><a href="#beranda" class="breadcrumb">Beranda / ${page.sem?'Semester '+page.sem.nomor:'Pengembangan diri'}</a><p class="eyebrow">${page.sem?esc(page.sem.sekolah):'REFLEKSI PROFESIONAL'}</p><h1>${esc(page.title)}</h1><p>${page.kind==='artifact'?'Bukti pembelajaran dan analisis pengalaman praktik.':'Dokumentasi perjalanan belajar menuju guru profesional.'}</p></section><section class="section">${body}</section>`}
document.body.classList.toggle('is-home',id==='beranda');document.querySelector('.hero-menu')?.addEventListener('click',e=>toggleMenu(e.currentTarget));document.title=(page?page.title+' — ':'')+'Dani | Portofolio PPG';document.body.classList.remove('menu-open');document.querySelector('#menuToggle').setAttribute('aria-expanded','false');window.scrollTo(0,0)}
function empty(title,text){return `<div class="empty"><span class="empty-icon">▤</span><h2>${title}</h2><p>${text}</p><span class="pill">MENUNGGU MATERI</span></div>`}
let preference;try{preference=localStorage.getItem('dani-theme')}catch{}
function theme(v){document.documentElement.dataset.theme=v;document.querySelector('#themeToggle').setAttribute('aria-label',v==='dark'?'Aktifkan mode terang':'Aktifkan mode gelap')}
theme(preference|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));
document.querySelector('#themeToggle').onclick=()=>{const v=document.documentElement.dataset.theme==='dark'?'light':'dark';theme(v);try{localStorage.setItem('dani-theme',v)}catch{}};
let menuTrigger;
const menuPanel=document.querySelector('#sidebar');
menuPanel.setAttribute('aria-label','Menu portofolio');
document.querySelector('#menuToggle').setAttribute('aria-controls','sidebar');
function positionMenu(trigger){const r=trigger.getBoundingClientRect();const vw=document.documentElement.clientWidth;const w=Math.min(350,vw-24);menuPanel.style.width=w+'px';menuPanel.style.right=Math.max(12,Math.min(vw-r.right,vw-w-12))+'px';const top=Math.max(12,Math.min(r.bottom+12,innerHeight-180));menuPanel.style.top=top+'px';menuPanel.style.maxHeight=(innerHeight-top-12)+'px'}
function closeMenu(restore=false){document.body.classList.remove('menu-open');document.querySelectorAll('#menuToggle,.hero-menu').forEach(b=>b.setAttribute('aria-expanded','false'));menuPanel.inert=true;if(restore)menuTrigger?.focus()}
function toggleMenu(trigger){if(document.body.classList.contains('menu-open'))return closeMenu();menuTrigger=trigger;positionMenu(trigger);menuPanel.inert=false;document.body.classList.add('menu-open');document.querySelectorAll('#menuToggle,.hero-menu').forEach(b=>b.setAttribute('aria-expanded','true'))}
menuPanel.inert=true;
document.querySelector('#menuToggle').onclick=e=>toggleMenu(e.currentTarget);
document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!menuPanel.contains(e.target)&&!e.target.closest('#menuToggle,.hero-menu'))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu(true)});
menuPanel.addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
window.addEventListener('resize',()=>{if(document.body.classList.contains('menu-open'))positionMenu(menuTrigger)});
window.addEventListener('scroll',()=>{if(document.body.classList.contains('menu-open'))closeMenu()},{passive:true});
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus()};
let routeTransition;
function navigatePage(){
  closeMenu();
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){render();main.focus({preventScroll:true});return}
  if(document.startViewTransition){
    routeTransition?.skipTransition();
    routeTransition=document.startViewTransition(()=>{render();main.focus({preventScroll:true})});
    routeTransition.finished.catch(()=>{});
  }else{
    main.getAnimations().forEach(a=>a.cancel());render();main.focus({preventScroll:true});
    main.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:240,easing:'cubic-bezier(.22,1,.36,1)'});
  }
}
window.addEventListener('hashchange',navigatePage);document.querySelector('#year').textContent=new Date().getFullYear();render();


